'use strict';
const scenarios=[
 {id:'dynamics',tab:'Dynamics change',tag:'Unexpected dynamics',title:'A correct model can become stale.',cohort:'30 starts per direction',description:'At 20 seconds, drag changes and all four landmarks move. Online CoPH identifies the new dynamics from executed transitions, while the initially correct fixed model retains its old value.',steps:['Drag changes from 0.25 to 0.45; goals also move.','Executed transitions reveal the dynamics mismatch.','Committed drag estimates and subsequent commands change.','Compare motion and post-change return with the stale model.'],limit:'Displayed seed 87000 is the lowest declared seed, selected without a seed search. The full study also tests drag 0.10. Native velocities and a spatial field were not retained.',clock:'Mission time is printed in each frame. Playback is compressed and includes extra frames around the intervention; it is not a real-time simulation.',events:[['Before change',19.9],['Dynamics change',20],['Identification updates',22.4],['Recorded horizon',40]],record:'https://github.com/SetasAditya/CoPH-Sense/blob/main/docs/results/native_drag_shift_v1/summary.json'},
 {id:'hazards',tab:'Different preferences',tag:'Shared evidence, individual objectives',title:'The scout crosses. The carrier detours.',cohort:'Four fixed hazard scenes',description:'In the two-mild-hazard scene, a risk-tolerant scout precedes a risk-averse carrier by 25 seconds. Shared graded evidence lets the carrier apply its own risk weight; dashed paths show the matched sender-advice reference.',steps:['The carrier has not visited the hazardous corridor.','The scout sends supported learned-field summaries.','The receiver prices the route with its own preferences.','Inspect the carrier path and its weighted risk exposure.'],limit:'Original animation seed 79000. The animation shows the field arm and a sender-advice reference; raw readings match navigation in the original pilot. Additional benefit from receiver fitting is unestablished.',clock:'Two agents share a simulation clock; the carrier activates at 25 s. Model surfaces use the exact logged control-time version and mask unsupported predictions.',events:[['Scout starts',0],['Carrier activates',25],['Inspect shared evidence',30],['Later route',55]],record:'https://github.com/SetasAditya/CoPH-Sense/blob/main/CoPH-Stagewise/HAZARD_DEMO.md'},
 {id:'reciprocity',tab:'Reciprocal discovery',tag:'Information changes discovery order',title:'One warning makes the next warning possible.',cohort:'Controlled crossing',description:'Agents start at opposite ends of a corridor network with hidden closures. An early warning redirects one agent; its changed route reaches a second blockage first and produces a useful return warning.',steps:['Each agent knows the surveyed network but not its closures.','A locally observed blockage is communicated.','The receiver revises its target and route.','An earlier return discovery reduces team detour.'],limit:'Original animation seed 76000. Solid paths use reciprocal exchange; dashed paths use no communication. Benefits are layout- and timing-dependent. Plants are independent, without inter-agent contact dynamics.',clock:'Mission time and exact model versions are printed in the video. The surface is shaping energy, not terrain elevation. World truth is shown only for evaluation.',events:[['Initial plans',0],['First warning',4.8],['Return warning',21.12],['Later progress',70]],record:'https://github.com/SetasAditya/CoPH-Sense/blob/main/CoPH-Stagewise/CROSSING_DEMO.md'},
 {id:'encounters',tab:'Symmetric encounter',tag:'Protected execution and liveness',title:'A deterministic rule clears a symmetric stall.',cohort:'30 starts per family',description:'Four agents swap goals through a common center. The shared final layer combines a braking-derived interaction range, contact prediction, least-violation control and deterministic priority. The matched base layer can remain stalled.',steps:['Simultaneous motion creates a symmetric conflict.','The execution layer uses local peer context.','Programmed priority changes the yielding target.','Compare goal progress and sampled separation.'],limit:'Seed 300 is the lowest declared evaluation seed. This is programmed yielding, not learned strategy discovery. Forces, yield events and model revisions are unavailable in these saved records.',clock:'Positions were subsampled after integration at 0.1, 0.5, …, 39.7 s, with the true initial state prepended. Sampled separation does not establish continuous-time safety.',events:[['Initial state',0],['Approaching conflict',4.1],['Passage',14.1],['Recorded end',39.7]],record:'https://github.com/SetasAditya/CoPH-Sense/blob/main/docs/results/native_final_layer_v1/summary.json'},
 {id:'uncertainty',tab:'Sparse evidence',tag:'Saved-state route decisions',title:'A useful estimate also marks ambiguity.',cohort:'12 groups × 400 path pairs',description:'Field, raw-reading and graded-costmap representations use identical evidence. Candidate paths are scored within supported regions. The video steps through the first 12 original queries and shows their archived certification flags and true decision regret.',steps:['Sparse observations leave route costs uncertain.','A field representation predicts values between anchors.','Each representation chooses between the same paths.','Inspect cost differences, certification flags and regret.'],limit:'This is a saved-state query sequence, not a navigation episode. Paths were regenerated from the original random seed and checked against archived prices. Sampling distributions were not retained.',clock:'The frame label is a query index, not mission time. The model surface is the supported value–gradient route scorer. No sampled cost distribution is invented.',events:[['First query',0],['Fourth query',3],['Eighth query',7],['Final displayed query',11]],record:'https://github.com/SetasAditya/CoPH-Sense/blob/main/docs/results/route_certificate_v1/summary.json'}
];
const video=document.getElementById('scenario-video');const speed=document.getElementById('playback-speed');speed.addEventListener('change',()=>{video.playbackRate=Number(speed.value)});let current=0;let provenance;
const tabs=document.getElementById('scenario-tabs');
scenarios.forEach((s,i)=>{const b=document.createElement('button');b.textContent=s.tab;b.id=`tab-${s.id}`;b.type='button';b.setAttribute('role','tab');b.setAttribute('aria-controls','scenario-video');b.addEventListener('click',()=>select(i));tabs.append(b)});
function updateEvents(){const ready=Boolean(provenance&&video.readyState>=1&&video.currentSrc.endsWith(`/assets/${scenarios[current].id}.mp4`));[...document.querySelectorAll('#event-buttons button')].forEach(b=>b.disabled=!ready)}
video.addEventListener('loadedmetadata',updateEvents);
function seek(s,value){if(!provenance||video.readyState<1)return;const frames=provenance.frames[s.id];if(!frames?.length)return;const key=s.id==='uncertainty'?'query_index':'mission_seconds';const nearest=frames.reduce((a,b)=>Math.abs(b[key]-value)<Math.abs(a[key]-value)?b:a);video.currentTime=nearest.video_seconds;video.pause()}
function select(i){current=i;const s=scenarios[i];[...tabs.children].forEach((b,k)=>{b.setAttribute('aria-selected',String(i===k));b.tabIndex=i===k?0:-1});video.pause();video.src=`assets/${s.id}.mp4`;video.poster=`assets/${s.id}.png`;video.setAttribute('aria-label',s.title);video.load();video.playbackRate=Number(speed.value);document.getElementById('scenario-tag').textContent=s.tag;document.getElementById('scenario-title').textContent=s.title;document.getElementById('scenario-description').textContent=s.description;document.getElementById('scenario-cohort').textContent=s.cohort;document.getElementById('scenario-limit').textContent=s.limit;document.getElementById('scenario-clock').textContent=s.clock;document.getElementById('gif-link').href=`assets/${s.id}.gif`;document.getElementById('frames-link').href=`records.html#${s.id}`;document.getElementById('summary-link').href=`results.html#${s.id}`;
 const box=document.getElementById('mechanism');box.replaceChildren();s.steps.forEach((t,k)=>{const d=document.createElement('div'),h=document.createElement('h4'),p=document.createElement('p');h.textContent=['Unknown','Evidence','Correction / action','Outcome'][k];p.textContent=t;d.append(h,p);box.append(d)});
 const events=document.getElementById('event-buttons');events.replaceChildren();s.events.forEach(([label,t])=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.disabled=true;b.addEventListener('click',()=>seek(s,t));events.append(b)});history.replaceState(null,'',`#${s.id}`)}
tabs.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const focused=[...tabs.children].indexOf(document.activeElement);select(((focused>=0?focused:current)+(e.key==='ArrowRight'?1:-1)+scenarios.length)%scenarios.length);tabs.children[current].focus()}});
fetch('assets/provenance.json').then(r=>{if(!r.ok)throw Error('Provenance unavailable');return r.json()}).then(p=>{provenance=p;updateEvents()}).catch(()=>{document.getElementById('scenario-clock').textContent+=' Frame provenance is temporarily unavailable; the video controls remain usable.'});
const initial=scenarios.findIndex(s=>`#${s.id}`===location.hash);select(initial<0?0:initial);
